try {
  let raw = $input.first().json.candidates[0].content.parts[0].text;

  raw = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

  const parsed = JSON.parse(raw);
  // Sin cabecera (p. ej. {"error": "PDF ilegible"}) lo tratamos como PDF ilegible
  if (parsed.error || !parsed.cabecera) throw new Error(parsed.error || 'respuesta sin cabecera');
  const numeroPedido = parsed.cabecera?.numero_pedido?.toString().trim();   // se conservan los ceros a la izquierda

  // Red de seguridad por si el agente no devuelve el array de líneas
  const cargasArray = parsed.cargas_descargas || [];

  return [{
    json: {
      cabecera: {
        ...parsed.cabecera,
        numero_pedido: numeroPedido
      },
      cargas_descargas: cargasArray,
      total_cargas: cargasArray.length,
      pdf_base64: $('Buscamos en Proceso').first().json.pdf_base64,
      id_proceso: $('Buscamos en Proceso').first().json.id_proceso.trim(),
      email_origen: $('Buscamos en Proceso').first().json.email_origen,
      nombre_remitente: $('Buscamos en Proceso').first().json.nombre_remitente,
      nombre_archivo: $('Buscamos en Proceso').first().json.nombre_archivo,
      fecha_recepcion: $('Buscamos en Proceso').first().json.fecha_recepcion,
      hora_recepcion: $('Buscamos en Proceso').first().json.hora_recepcion,
      asunto_email: $('Buscamos en Proceso').first().json.asunto_email
    }
  }];
} catch(e) {
  return [{
    json: {
      error: 'JSON malformado: ' + e.message,
      raw_length: $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text?.length || 0,
      id_proceso: $('Buscamos en Proceso').first().json.id_proceso,
      nombre_archivo: $('Buscamos en Proceso').first().json.nombre_archivo,
      email_origen: $('Buscamos en Proceso').first().json.email_origen
    }
  }];
}

let results = [];

// Recorremos cada elemento que entra al nodo
for (const item of $input.all()) {
  const cargas = item.json.cargas_descargas || [];
  //console.log('cargas:', cargas);
  cargas.forEach(carga => {
    // Extraemos el array de mercancias de esta carga
    const mercancias = carga.mercancias || [];
    //console.log('mercancias:', mercancias);
    // Creamos una copia de la carga SIN el array de detalles para no duplicar datos pesados
    carga.temperatura = carga.temperatura;
    //const { detalle_carga, ...datosCarga } = carga;
    if (mercancias.length > 0) {
      mercancias.forEach(mercancia => {
        delete carga.mercancias;
        results.push({ cargas : {
          // Combinamos los datos de la carga con los del detalle
          ...carga,
          ...mercancia
        }});
      });
    } else {
      results.push({ cargas : {
          ...carga
        }});
    }
  });
}
//console.log('results:', results);
return results;

