// Respuesta de /api/pedido/existe. Ante cualquier duda (error, tiempo agotado, respuesta rara) el pedido sigue el camino de siempre: Pendiente y revisión humana
const r = $input.first().json || {};
const esSi = v => v === true || ['true', 's', 'si', 'sí'].includes(String(v).trim().toLowerCase());
let existe = false, actualizar = false, pedido = '', info = '', consulta = 'ok';

if (r.error || typeof r.existe === 'undefined') {
  consulta = 'sin respuesta válida';
  const e = r.error;
  info = e ? (typeof e === 'string' ? e : (e.message || JSON.stringify(e))) : 'La API no devolvió el campo "existe"';
} else {
  existe = esSi(r.existe);
  actualizar = existe && esSi(r.actualizar);
  pedido = String(r.pedido ?? '').trim();
  info = String(r.info ?? '');
}

return [{
  json: {
    existe,
    actualizar,
    duplicado_sin_actualizar: existe && !actualizar,
    pedido,
    info: info.slice(0, 300),
    consulta
  }
}];

